export function retentionDays(env: Pick<Env, 'LEDGER_RETENTION_DAYS'>): number {
  const n = Number(env.LEDGER_RETENTION_DAYS);
  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : DEFAULT_RETENTION_DAYS;
}

